// ============================================================================
// FreeLang RPC 모듈 - Channel 기반 네트워크 통신
// ============================================================================
// 목표: Zero-Copy-DB에서 분산 노드 간 원격 함수 호출(RPC)을 구현
// 원리:
//   1. concurrent.Channel을 양방향 파이프로 사용 (네트워크 시뮬레이션)
//   2. 메시지는 전역 풀에 저장 후 인덱스를 i64로 전달
//   3. 동기 호출: 응답 채널에서 max 100 tick 폴링
//   4. 핸들러는 if체인 디스패치로 구현
// 구조:
//   - 상수 정의 (메시지 타입, 에러 코드)
//   - Message, Transport, Client, Server 구조체
//   - @inline 헬퍼
//   - 팩토리 함수
//   - Transport 파이프 (양방향 채널 쌍)
//   - Client: 동기 호출, inflight 관리
//   - Server: 핸들러 등록, 요청 디스패치
// ============================================================================

module rpc {
    // === 상수: 메시지 타입 ===
    const MSG_REQUEST:  i32 = 1;
    const MSG_RESPONSE: i32 = 2;
    const MSG_ERROR:    i32 = 3;
    const MSG_PING:     i32 = 4;
    const MSG_PONG:     i32 = 5;

    // === 상수: 에러 코드 ===
    const RPC_OK:             i32 = 0;
    const RPC_ERR_NOT_FOUND:  i32 = 1;
    const RPC_ERR_TIMEOUT:    i32 = 2;
    const RPC_ERR_NO_HANDLER: i32 = 3;
    const RPC_ERR_CLOSED:     i32 = 4;

    // === 상수: 프로토콜 파라미터 ===
    const PROTO_VERSION:  i32 = 1;
    const MAX_INFLIGHT:   i32 = 64;
    const MAX_METHODS:    i32 = 16;
    const MAX_MESSAGES:   i32 = 256;
    const RECV_TIMEOUT:   i32 = 100;   // tick 단위

    // === 데이터 구조체 ===
    // RPC 메시지 (20 바이트 헤더 시뮬레이션)
    struct Message {
        msg_type:   i32;        // MSG_REQUEST / MSG_RESPONSE / MSG_ERROR / MSG_PING / MSG_PONG
        msg_id:     i64;        // 단조 증가 ID
        method:     string;     // "kv.set", "kv.get", "ping", ...
        payload:    i64;        // 직렬화된 페이로드 (i64로 단순화)
        error_msg:  string;     // 에러 메시지 (비어있으면 성공)
    }

    // 네트워크 추상화 (채널 기반 양방향 파이프)
    struct Transport {
        send_ch:    concurrent.Channel;  // 송신 채널
        recv_ch:    concurrent.Channel;  // 수신 채널
        node_id:    string;
        is_open:    bool;
    }

    // RPC 클라이언트 (동기 호출 에뮬레이션)
    struct Client {
        transport:          Transport;
        next_msg_id:        i64;
        // inflight 테이블: 병렬 배열
        inflight_ids:       [i64];
        inflight_chans:     [concurrent.Channel];
        inflight_count:     i32;
    }

    // RPC 서버 (핸들러 등록 & 디스패치)
    struct Server {
        transport:      Transport;
        methods:        [string];       // 등록된 메서드 목록
        method_count:   i32;
        is_running:     bool;
    }

    // === 전역 메시지 풀 (Message 객체 저장) ===
    // 제네릭이 없으므로 배열로 메시지 저장, 인덱스를 i64로 전달
    let g_msg_pool:      [Message];
    let g_msg_pool_count: i32 = 0;

    // === 전역 메시지 ID 카운터 ===
    let g_next_msg_id: i64 = 1;

    // === @inline 헬퍼 함수 ===

    @inline
    func is_message_valid(msg: Message) -> bool {
        return msg.msg_type >= MSG_REQUEST && msg.msg_type <= MSG_PONG;
    }

    @inline
    func msg_is_error(msg: Message) -> bool {
        return len(msg.error_msg) > 0;
    }

    // === 팩토리 함수 ===

    // Transport 생성 (단일 노드, 채널 초기화)
    func rpc_transport_new(node_id: string) -> Transport {
        return Transport{
            send_ch:    concurrent.chan_new(10),
            recv_ch:    concurrent.chan_new(10),
            node_id:    node_id,
            is_open:    true,
        };
    }

    // 양방향 파이프: 두 Transport를 연결 (A.send → B.recv, B.send → A.recv)
    func transport_pipe_new(node_a: string, node_b: string) -> (Transport, Transport) {
        // 실제 구현: 같은 채널을 반대로 지정
        // 여기서는 각각 독립적인 채널을 만들고 시뮬레이션
        let ch_a_to_b = concurrent.chan_new(10);
        let ch_b_to_a = concurrent.chan_new(10);

        let t_a = Transport{
            send_ch:    ch_a_to_b,
            recv_ch:    ch_b_to_a,
            node_id:    node_a,
            is_open:    true,
        };
        let t_b = Transport{
            send_ch:    ch_b_to_a,
            recv_ch:    ch_a_to_b,
            node_id:    node_b,
            is_open:    true,
        };
        return (t_a, t_b);
    }

    // Client 생성
    func rpc_client_new(transport: Transport) -> Client {
        return Client{
            transport:          transport,
            next_msg_id:        1,
            inflight_ids:       make([i64], MAX_INFLIGHT),
            inflight_chans:     make([concurrent.Channel], MAX_INFLIGHT),
            inflight_count:     0,
        };
    }

    // Server 생성
    func rpc_server_new(transport: Transport) -> Server {
        return Server{
            transport:      transport,
            methods:        make([string], MAX_METHODS),
            method_count:   0,
            is_running:     true,
        };
    }

    // === 메시지 생성 함수 ===

    func make_request(msg_id: i64, method: string, payload: i64) -> Message {
        return Message{
            msg_type:   MSG_REQUEST,
            msg_id:     msg_id,
            method:     method,
            payload:    payload,
            error_msg:  "",
        };
    }

    func make_response(msg_id: i64, payload: i64) -> Message {
        return Message{
            msg_type:   MSG_RESPONSE,
            msg_id:     msg_id,
            method:     "",
            payload:    payload,
            error_msg:  "",
        };
    }

    func make_error_msg(msg_id: i64, error: string) -> Message {
        return Message{
            msg_type:   MSG_ERROR,
            msg_id:     msg_id,
            method:     "",
            payload:    0,
            error_msg:  error,
        };
    }

    func make_ping() -> Message {
        return Message{
            msg_type:   MSG_PING,
            msg_id:     0,
            method:     "",
            payload:    0,
            error_msg:  "",
        };
    }

    func make_pong() -> Message {
        return Message{
            msg_type:   MSG_PONG,
            msg_id:     0,
            method:     "",
            payload:    0,
            error_msg:  "",
        };
    }

    // === Transport 함수 ===

    // 메시지 전송 (채널에 인덱스 저장)
    func (t: *Transport) transport_send(msg: Message) -> bool {
        if !t.is_open {
            return false;
        }
        // 메시지 풀에 저장
        if g_msg_pool_count >= MAX_MESSAGES {
            return false;  // 풀 가득 참
        }
        g_msg_pool[g_msg_pool_count] = msg;
        let msg_idx = i64(g_msg_pool_count);
        g_msg_pool_count = g_msg_pool_count + 1;

        // 인덱스를 채널에 전송
        return t.send_ch.chan_send(msg_idx);
    }

    // 메시지 수신 (채널에서 인덱스 읽기)
    func (t: *Transport) transport_recv() -> (Message, bool) {
        if !t.is_open {
            return (make_ping(), false);
        }
        let msg_idx, ok = t.recv_ch.chan_recv();
        if !ok {
            return (make_ping(), false);
        }
        if msg_idx < 0 || msg_idx >= i64(g_msg_pool_count) {
            return (make_ping(), false);
        }
        return (g_msg_pool[i32(msg_idx)], true);
    }

    // Transport 종료
    func (t: *Transport) transport_close() {
        t.is_open = false;
        t.send_ch.chan_close();
        t.recv_ch.chan_close();
    }

    // === Client 함수 ===

    // 단조 증가 메시지 ID 생성
    func (cli: *Client) next_id() -> i64 {
        let id = g_next_msg_id;
        g_next_msg_id = g_next_msg_id + 1;
        return id;
    }

    // Inflight 요청 등록
    func (cli: *Client) register_inflight(msg_id: i64, ch: concurrent.Channel) -> bool {
        if cli.inflight_count >= MAX_INFLIGHT {
            return false;
        }
        cli.inflight_ids[cli.inflight_count] = msg_id;
        cli.inflight_chans[cli.inflight_count] = ch;
        cli.inflight_count = cli.inflight_count + 1;
        return true;
    }

    // Inflight 요청 완료 (응답 채널에 메시지 저장)
    func (cli: *Client) complete_inflight(msg_id: i64, resp: Message) -> bool {
        let i = 0;
        for i = 0; i < cli.inflight_count; i = i + 1 {
            if cli.inflight_ids[i] == msg_id {
                // 응답을 메시지 풀에 저장 후 인덱스를 채널에 전송
                if g_msg_pool_count >= MAX_MESSAGES {
                    return false;
                }
                g_msg_pool[g_msg_pool_count] = resp;
                let resp_idx = i64(g_msg_pool_count);
                g_msg_pool_count = g_msg_pool_count + 1;
                let ok = cli.inflight_chans[i].chan_send(resp_idx);
                return ok;
            }
        }
        return false;
    }

    // Inflight 요청 취소
    func (cli: *Client) cancel_inflight(msg_id: i64) {
        let i = 0;
        let j = 0;
        for i = 0; i < cli.inflight_count; i = i + 1 {
            if cli.inflight_ids[i] != msg_id {
                cli.inflight_ids[j] = cli.inflight_ids[i];
                cli.inflight_chans[j] = cli.inflight_chans[i];
                j = j + 1;
            }
        }
        cli.inflight_count = j;
    }

    // 동기 RPC 호출 (100 tick 폴링)
    func (cli: *Client) rpc_call(method: string, payload: i64) -> (Message, bool) {
        let msg_id = cli.next_id();
        let req = make_request(msg_id, method, payload);

        // 응답 채널 생성 (용량 1)
        let resp_ch = concurrent.chan_new(1);

        // Inflight 등록
        let ok = cli.register_inflight(msg_id, resp_ch);
        if !ok {
            return (make_error_msg(msg_id, "too many inflight requests"), false);
        }

        // 요청 전송
        let ok2 = cli.transport.transport_send(req);
        if !ok2 {
            cli.cancel_inflight(msg_id);
            return (make_error_msg(msg_id, "transport send failed"), false);
        }

        // 응답 대기 (최대 RECV_TIMEOUT tick)
        let t = 0;
        for t = 0; t < RECV_TIMEOUT; t = t + 1 {
            let resp_idx, ok3 = resp_ch.chan_recv();
            if ok3 {
                if resp_idx < 0 || resp_idx >= i64(g_msg_pool_count) {
                    return (make_error_msg(msg_id, "invalid response index"), false);
                }
                return (g_msg_pool[i32(resp_idx)], true);
            }
        }

        // 타임아웃
        cli.cancel_inflight(msg_id);
        return (make_error_msg(msg_id, "timeout"), false);
    }

    // === Server 함수 ===

    // 핸들러 등록
    func (srv: *Server) rpc_register(method: string) -> bool {
        if srv.method_count >= MAX_METHODS {
            return false;
        }
        srv.methods[srv.method_count] = method;
        srv.method_count = srv.method_count + 1;
        return true;
    }

    // 메서드 등록 확인
    func (srv: *Server) has_method(method: string) -> bool {
        let i = 0;
        for i = 0; i < srv.method_count; i = i + 1 {
            if srv.methods[i] == method {
                return true;
            }
        }
        return false;
    }

    // 실제 핸들러 구현 (if체인 디스패치)
    func (srv: *Server) dispatch_inner(method: string, req: Message) -> Message {
        // ping 핸들러
        if method == "ping" {
            return make_response(req.msg_id, 0);
        }
        // kv.set 핸들러
        if method == "kv.set" {
            // payload = key_hash (단순화)
            return make_response(req.msg_id, 1);  // 성공
        }
        // kv.get 핸들러
        if method == "kv.get" {
            return make_response(req.msg_id, 0);  // 값 = 0 (없음)
        }
        // kv.delete 핸들러
        if method == "kv.delete" {
            return make_response(req.msg_id, 1);  // 성공
        }
        // raft.vote 핸들러
        if method == "raft.vote" {
            return make_response(req.msg_id, 1);  // 투표
        }
        // raft.append 핸들러
        if method == "raft.append" {
            return make_response(req.msg_id, 1);  // 성공
        }
        // 알 수 없는 메서드
        return make_error_msg(req.msg_id, "method not found");
    }

    // 단일 요청 처리 (한 번에 하나의 메시지)
    func (srv: *Server) serve_one() -> bool {
        if !srv.is_running {
            return false;
        }
        let req, ok = srv.transport.transport_recv();
        if !ok {
            return false;
        }

        // 요청이 아니면 무시
        if req.msg_type != MSG_REQUEST {
            return false;
        }

        // 핸들러 디스패치
        let resp = srv.dispatch_inner(req.method, req);

        // 응답 전송
        let ok2 = srv.transport.transport_send(resp);
        return ok2;
    }

    // === 통계 함수 ===

    func (cli: *Client) rpc_stats() -> string {
        let msg = "[RPC Client] next_msg_id=" + i64_to_string(cli.next_msg_id) + " inflight=" + i32_to_string(cli.inflight_count);
        return msg;
    }

    func (srv: *Server) rpc_stats() -> string {
        let msg = "[RPC Server] methods=" + i32_to_string(srv.method_count) + " running=" + (if srv.is_running { "true" } else { "false" });
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }

    @inline
    func i64_to_string(n: i64) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n < 0 { return "-" + i64_to_string(-n); }
        return i32_to_string(i32(n));
    }
}

// === 테스트 시나리오 (주석) ===
//
// RPC 기본 동작:
//   - rpc_transport_new("client") → Transport{ node_id: "client" }
//   - transport_pipe_new("client", "server") → (Transport, Transport) 쌍
//
//   - rpc_client_new(t) → Client{ transport: t }
//   - rpc_server_new(t) → Server{ transport: t }
//
//   - srv.rpc_register("ping") → true
//   - cli.rpc_call("ping", 0) → (Message{ msg_type: MSG_RESPONSE }, true)
//
// 메시지 흐름:
//   1. cli.rpc_call("ping", 0) 호출
//   2. Client가 MSG_REQUEST 생성 및 전송
//   3. Server가 transport_recv()로 수신
//   4. dispatch_inner("ping", req) → MSG_RESPONSE 생성
//   5. Server가 transport_send()로 응답 전송
//   6. Client가 응답 채널에서 수신
//   7. (Message, true) 반환
//

// ============================================================================
// FreeLang I/O 모듈 - 파일 및 디렉토리 시스템 인터페이스
// ============================================================================
// 목표: Zero-Copy-DB에서 설정 파일, 벤치마크 결과, 로그 등을 읽고 쓸 수 있도록 함
// 원리:
//   1. 모든 파일 I/O 함수는 (value, bool) 다중 반환으로 성공/실패 구분
//   2. sys_* 브리지 함수를 통해 런타임이 실제 OS 시스템 콜 오버라이드 가능
//   3. 에러 코드로 근본 원인 추적 가능
// 구조:
//   - 에러 상수 정의
//   - 데이터 구조체 (FileResult, DirEntry)
//   - 경로 조작 헬퍼 (join_path, basename, dirname)
//   - 내부 헬퍼 (@inline split_lines)
//   - 시스템 브리지 함수 (sys_*)
//   - 공개 API (read_file, write_file, append_file, file_exists, read_lines, list_dir)
// ============================================================================

module io {
    // === 에러 코드 ===
    const ERR_OK:         i32 = 0;
    const ERR_NOT_FOUND:  i32 = 1;
    const ERR_PERMISSION: i32 = 2;
    const ERR_IO:         i32 = 3;
    const ERR_INVALID:    i32 = 4;

    // === 데이터 구조체 ===
    // 파일 작업 결과 컨텍스트
    struct FileResult {
        success:          bool;
        error_code:       i32;
        bytes_processed:  u64;
    }

    // 디렉토리 항목 (list_dir 반환값)
    struct DirEntry {
        name:   string;
        is_dir: bool;
        size:   u64;
    }

    // === 내부 헬퍼 함수 ===
    // '\n'을 기준으로 문자열을 라인으로 분할
    @inline
    func split_lines(content: string) -> [string] {
        let lines = make([string], 0);
        let current = "";
        let i = 0;
        let len_val = len(content);

        for i = 0; i < len_val; i = i + 1 {
            let ch_code = char_at(content, i);
            if ch_code == 10 {  // '\n'
                lines.push(current);
                current = "";
            } else if ch_code == 13 {  // '\r' (Windows)
                // Skip carriage return
            } else {
                let ch = char_from_code(ch_code);
                current = current + ch;
            }
        }
        // 마지막 줄 추가 (개행 없으면)
        if len(current) > 0 {
            lines.push(current);
        }
        return lines;
    }

    // === 시스템 브리지 함수 (런타임 오버라이드 지점) ===
    // 이 함수들은 런타임이 실제 OS 시스템 콜로 대체해야 함

    // Linux: open(path, O_RDONLY), read(fd, buf, size), close(fd)
    func sys_read_file(path: string) -> (string, i32) {
        // 모의 구현: 파일을 읽지 못함
        // 실제 구현은 런타임이 제공해야 함
        if len(path) == 0 {
            return ("", ERR_INVALID);
        }
        // 기본적으로 파일을 찾을 수 없다고 시뮬레이션
        return ("", ERR_NOT_FOUND);
    }

    // Linux: open(path, O_WRONLY|O_CREAT), write(fd, buf, size), close(fd)
    func sys_write_file(path: string, content: string, append: bool) -> i32 {
        if len(path) == 0 {
            return ERR_INVALID;
        }
        // 모의 구현: 항상 성공
        return ERR_OK;
    }

    // Linux: access(path, F_OK)
    func sys_file_exists(path: string) -> bool {
        if len(path) == 0 {
            return false;
        }
        return false;  // 모의 구현
    }

    // Linux: opendir(path), readdir(), closedir()
    func sys_list_dir(path: string) -> ([string], i32) {
        if len(path) == 0 {
            return (make([string], 0), ERR_INVALID);
        }
        return (make([string], 0), ERR_NOT_FOUND);
    }

    // === 공개 API ===

    // path에서 파일 내용 전체 읽기
    // 성공: (content, true), 실패: ("", false)
    func read_file(path: string) -> (string, bool) {
        if len(path) == 0 {
            return ("", false);
        }
        let content, err = sys_read_file(path);
        return (content, err == ERR_OK);
    }

    // path에 content를 쓰기 (덮어쓰기)
    func write_file(path: string, content: string) -> bool {
        if len(path) == 0 {
            return false;
        }
        let err = sys_write_file(path, content, false);
        return err == ERR_OK;
    }

    // path에 content를 덧붙이기
    func append_file(path: string, content: string) -> bool {
        if len(path) == 0 {
            return false;
        }
        let err = sys_write_file(path, content, true);
        return err == ERR_OK;
    }

    // path 파일 존재 여부 확인
    func file_exists(path: string) -> bool {
        if len(path) == 0 {
            return false;
        }
        return sys_file_exists(path);
    }

    // path 파일을 읽고 줄별로 분할
    // '\n'을 기준으로 분할하여 [string] 배열로 반환
    func read_lines(path: string) -> ([string], bool) {
        if len(path) == 0 {
            return (make([string], 0), false);
        }
        let content, ok = read_file(path);
        if !ok {
            return (make([string], 0), false);
        }
        let lines = split_lines(content);
        return (lines, true);
    }

    // path 디렉토리의 항목 목록 조회
    // 성공: ([항목들], true), 실패: ([], false)
    func list_dir(path: string) -> ([string], bool) {
        if len(path) == 0 {
            return (make([string], 0), false);
        }
        let entries, err = sys_list_dir(path);
        return (entries, err == ERR_OK);
    }

    // === 경로 조작 헬퍼 ===

    // dir과 file을 경로로 결합
    // 예: join_path("/data", "config.json") → "/data/config.json"
    func join_path(dir: string, file: string) -> string {
        if len(dir) == 0 {
            return file;
        }
        if len(file) == 0 {
            return dir;
        }
        // dir이 "/"로 끝나는지 확인 필요 (문자 인덱싱 미지원 가정)
        // 간단한 구현: 항상 "/" 추가
        return dir + "/" + file;
    }

    // path에서 마지막 "/"까지의 디렉토리 부분 추출
    // 예: basename("/data/config.json") → "config.json"
    func basename(path: string) -> string {
        if len(path) == 0 {
            return "";
        }
        // "/" 기준으로 마지막 세그먼트 반환
        let last_slash_idx = string_last_index_of(path, "/");
        if last_slash_idx < 0 {
            return path;  // "/" 없으면 전체
        }
        return string_substring(path, last_slash_idx + 1, len(path));
    }

    // path에서 마지막 "/" 이전 부분 추출
    // 예: dirname("/data/config.json") → "/data"
    func dirname(path: string) -> string {
        if len(path) == 0 {
            return "";
        }
        // "/" 기준으로 마지막 세그먼트 제거
        let last_slash_idx = string_last_index_of(path, "/");
        if last_slash_idx <= 0 {
            return "/";  // "/" 없거나 루트
        }
        return string_substring(path, 0, last_slash_idx);
    }

    // === 정보성 함수 ===

    // FileResult 구조체를 문자열로 변환 (디버그용)
    func (fr: *FileResult) to_string() -> string {
        let status = if fr.success { "OK" } else { "FAIL" };
        let msg = "[FileResult] status=" + status + " error_code=" + i32_to_string(fr.error_code) + " bytes=" + u64_to_string(fr.bytes_processed);
        return msg;
    }

    // i32를 문자열로 변환 (헬퍼)
    @inline
    func i32_to_string(n: i32) -> string {
        // Note: 런타임이 제공하는 내장 함수 또는 직접 구현 필요
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        return "?";
    }

    // u64를 문자열로 변환 (헬퍼)
    @inline
    func u64_to_string(n: u64) -> string {
        return "0x" + i32_to_string(i32(n));
    }
