	}

	l.listener = ln
	fmt.Printf("[TCPListener] Listening on %s\n", l.addr)

	// Accept loop
	for {
		select {
		case <-l.done:
			fmt.Println("[TCPListener] Shutting down...")
			return ln.Close()
		default:
		}

		conn, err := ln.Accept()
		if err != nil {
