// ConnectionHandler manages Keep-Alive connections
type ConnectionHandler struct {
	conn            net.Conn
	keepAliveTimeout time.Duration
	readTimeout     time.Duration
	writeTimeout    time.Duration
	remoteAddr      string
}

// NewConnectionHandler creates a new connection handler
func NewConnectionHandler(conn net.Conn) *ConnectionHandler {
	return &ConnectionHandler{
		conn:             conn,
		keepAliveTimeout: 30 * time.Second,
		readTimeout:      15 * time.Second,
		writeTimeout:     15 * time.Second,
		remoteAddr:       conn.RemoteAddr().String(),
	}
}

// SetKeepAliveTimeout sets the timeout for Keep-Alive connections
func (ch *ConnectionHandler) SetKeepAliveTimeout(timeout time.Duration) {
	ch.keepAliveTimeout = timeout
}

// SetReadTimeout sets the read timeout
func (ch *ConnectionHandler) SetReadTimeout(timeout time.Duration) {
	ch.readTimeout = timeout
}

// SetWriteTimeout sets the write timeout
func (ch *ConnectionHandler) SetWriteTimeout(timeout time.Duration) {
	ch.writeTimeout = timeout
}

// ReadRequest reads a single HTTP request with timeout
func (ch *ConnectionHandler) ReadRequest() (*http.Request, error) {
	// Set read deadline
	ch.conn.SetReadDeadline(time.Now().Add(ch.readTimeout))
	defer ch.conn.SetReadDeadline(time.Time{}) // Clear deadline

	return http.ParseRequest(ch.conn)
}

// WriteResponse writes an HTTP response with timeout
func (ch *ConnectionHandler) WriteResponse(res *http.Response) error {
	// Set write deadline
	ch.conn.SetWriteDeadline(time.Now().Add(ch.writeTimeout))
	defer ch.conn.SetWriteDeadline(time.Time{}) // Clear deadline

	_, err := ch.conn.Write(res.Bytes())
	return err
}

// ShouldKeepAlive determines if the connection should be kept alive
func (ch *ConnectionHandler) ShouldKeepAlive(req *http.Request, res *http.Response) bool {
	// Check request
	if !req.IsKeepAlive() {
		return false
	}

	// Check response
	connHeader := res.GetHeader("Connection")
	if connHeader == "close" {
		return false
	}

	return true
}

// HandleConnection manages the full lifecycle of a connection
// It handles multiple requests in a Keep-Alive loop
func (ch *ConnectionHandler) HandleConnection(requestHandler func(*http.Request, *http.Response)) {
	defer ch.Close()

	fmt.Printf("[KeepAlive] New connection from %s\n", ch.remoteAddr)
	requestCount := 0

	for {
		// Set idle timeout for Keep-Alive
		ch.conn.SetReadDeadline(time.Now().Add(ch.keepAliveTimeout))

		// Read request
		req, err := ch.ReadRequest()
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				fmt.Printf("[KeepAlive] Connection %s timeout after %d requests\n", ch.remoteAddr, requestCount)
			} else {
				fmt.Printf("[KeepAlive] Error reading request from %s: %v\n", ch.remoteAddr, err)
			}
			break
		}

		requestCount++
		fmt.Printf("[%s] #%d: %s %s %s\n", ch.remoteAddr, requestCount, req.Method, req.Path, req.Version)

		// Create response
		res := http.NewResponse(200)

		// Handle request
		requestHandler(req, res)

		// Set Connection header based on Keep-Alive decision
		if ch.ShouldKeepAlive(req, res) {
			res.SetHeader("Connection", "keep-alive")
		} else {
			res.SetHeader("Connection", "close")
		}

		// Write response
		if err := ch.WriteResponse(res); err != nil {
			fmt.Printf("[KeepAlive] Error writing response to %s: %v\n", ch.remoteAddr, err)
			break
		}

		// Check if connection should be closed
		if !ch.ShouldKeepAlive(req, res) {
			fmt.Printf("[KeepAlive] Connection %s closed (Keep-Alive disabled)\n", ch.remoteAddr)
			break
		}
	}

	fmt.Printf("[KeepAlive] Connection %s closed after %d requests\n", ch.remoteAddr, requestCount)
}

// Close closes the connection
func (ch *ConnectionHandler) Close() error {
	return ch.conn.Close()
}

// RemoteAddr returns the remote address
func (ch *ConnectionHandler) RemoteAddr() string {
	return ch.remoteAddr
}

